import { readdir, readFile, writeFile } from "node:fs/promises";
const dir = new URL("../migrations/", import.meta.url);
const all = (await readdir(dir)).filter((name) => name.endsWith(".sql")).sort();
for (const [output, min] of [
  ["upgrade.sql", "0018a_review_contract.sql"],
  ["completion.sql", "0051_safety_and_messaging.sql"],
]) {
  const files = all.filter((name) => name >= min!);
  let sql =
    "-- GENERATED by npm run db:bundle. Review FOUNDER_HANDOFF.md; never auto-apply.\nBEGIN;\n";
  sql += `DO $$ BEGIN
 IF to_regclass('public.profiles') IS NULL OR to_regclass('public.certifications') IS NULL
 OR to_regclass('public.trainer_videos') IS NULL OR to_regclass('public.live_sessions') IS NULL
 OR to_regclass('public.trainer_earnings') IS NULL OR to_regclass('public.trainer_busy') IS NULL
 THEN RAISE EXCEPTION 'Historical base schema incomplete. Stop and review SQL_PLAN.md.'; END IF;
END $$;\n`;
  if (output === "completion.sql")
    sql += `DO $$ BEGIN
 IF to_regclass('public.wallet_token_units') IS NULL OR to_regclass('public.private_booking_holds') IS NULL
 OR to_regprocedure('public.trainer_is_eligible(uuid,boolean)') IS NULL
 OR NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='certificate_update_guard' AND permissive='RESTRICTIVE')
 THEN RAISE EXCEPTION '0050 baseline not reconciled. Use reviewed full upgrade after staging preflight.'; END IF;
END $$;\n`;
  for (const file of files)
    sql += `\n-- FILE: ${file}\n${await readFile(new URL(file, dir), "utf8")}\n`;
  sql += "COMMIT;\n";
  await writeFile(new URL(`../docs/launch/${output}`, import.meta.url), sql);
  console.log(
    `${output}: ${files.length} ordered migrations bundled. No SQL executed.`,
  );
}
